guess.py.src:
secret = 7
tries = 0
while True:
    guess = int(input("Your guess: "))
    tries = tries + 1
    if guess == secret:
        print("Got it in", tries, "tries!")
        break
    elif guess < secret:
        print("Too low.")
    else:
        print("Too high.")

